[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$utf8=New-Object Text.UTF8Encoding($false,$true)
function Write-NewJson([string]$Path,$Value,[int]$Depth=40){if(Test-Path -LiteralPath $Path){throw "Create-new failure evidence exists: $Path"};$json=($Value|ConvertTo-Json -Depth $Depth).Replace("`r`n","`n").Replace("`r","`n")+"`n";$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,$json,$utf8);[IO.File]::Move($tmp,$Path)}
$manifestPath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Partial_Manifest.v1.json'
$failurePath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Failure.v1.json'
$checkpointPath=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Checkpoint.v1.json'
$created=@(
 'Research\Gate13R36hConcurrencyPreparationV14.psm1','Research\Run-Gate13R36hBlockV14.ps1','Research\Run-Gate13R36hTelemetryProbeV14.ps1','Research\Initialize-Gate13R36hLaneCopiesV14.ps1','Research\Run-Gate13R36hConcurrencyPilotV14.ps1','Research\Analyze-Gate13R36hConcurrencyPilotV14.ps1',
 'Research\Verification\New-Gate13R36hPilotScheduleV14.ps1','Research\Verification\Run-Gate13R36hStaticUnitV14.ps1','Research\Verification\Run-Gate13R36hRetainedRegressionV14.ps1','Research\Verification\Run-Gate13R36hVerificationV14.ps1','Research\Verification\Run-Gate13R36hValidationOnlyPrePilotAuditV14.ps1','Research\Verification\Run-Gate13R36hLockHygieneUnitV14.ps1','Research\Verification\Run-Gate13R36hLaneBootstrapCompileV14.ps1',
 'Research\Gate13R_36h_10pct_4Lane_Pilot_Plan.v14.json','Research\Gate13R_36h_10pct_4Lane_Pilot_Schedule.v14.json','Research\Gate13R_36h_10pct_4Lane_Pilot_Schedule_Generation.v14.json'
)
$files=New-Object Collections.Generic.List[object]
foreach($relative in $created){$path=Join-Path $ProjectPath $relative;if(Test-Path -LiteralPath $path -PathType Leaf){$item=Get-Item -LiteralPath $path;$files.Add([pscustomobject][ordered]@{relativePath=$relative.Replace('\','/');bytes=[long]$item.Length;sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()})}}
$errorText='ConvertTo-Json rejected requested serialization depth 110 because Windows PowerShell 5.1 permits a maximum depth of 100; provenance and derivation receipt were not created.'
Write-NewJson $manifestPath ([ordered]@{schemaVersion=1;manifestKind='gate13r-36h-attempt14-derivation-partial-output-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-NO-RESUME';fileCount=$files.Count;files=$files.ToArray();verificationRootCreated=$false;cloneRootCreated=$false;pilotRootCreated=$false;formalRootCreated=$false;pilotStarted=$false;formalCampaign=$false}) 50
Write-NewJson $failurePath ([ordered]@{schemaVersion=1;failureKind='gate13r-36h-attempt14-derivation-failure-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-NO-RESUME';stage='provenance-serialization';error=$errorText;partialManifestRelativePath='Research/Gate13R_36h_10pct_4Lane_Attempt14_Derivation_Partial_Manifest.v1.json';partialManifestSha256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant();automaticRetryAttempted=$false;sameAttemptResumeAllowed=$false;pilotStarted=$false;formalCampaign=$false}) 30
Write-NewJson $checkpointPath ([ordered]@{schemaVersion=1;checkpointKind='gate13r-36h-attempt14-derivation-checkpoint-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');status='failed-no-resume';stage='provenance-serialization';error=$errorText;failureReceiptSha256=(Get-FileHash -LiteralPath $failurePath -Algorithm SHA256).Hash.ToLowerInvariant();partialManifestSha256=(Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant();verificationRootCreated=$false;cloneRootCreated=$false;pilotRootCreated=$false;formalRootCreated=$false}) 30
[pscustomobject]@{failureSha256=(Get-FileHash $failurePath -Algorithm SHA256).Hash.ToLowerInvariant();manifestSha256=(Get-FileHash $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant();checkpointSha256=(Get-FileHash $checkpointPath -Algorithm SHA256).Hash.ToLowerInvariant();partialFileCount=$files.Count}|ConvertTo-Json
